"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[9635],{25515:e=>{e.exports=JSON.parse('{"functions":[],"properties":[],"types":[],"name":"PerkEffectsDispatcher","desc":"The single writer of the perk buff folders. Personal buffs go to\\n`ReplicatedStorage/PerkBuffs/<UserId>` (one attribute per buff key); party\\nbuffs go to `ReplicatedStorage/PartyPerkBuffs` from the per-perk MAX level\\nacross all players (the \\"only highest active\\" rule), plus `<PerkId>Level`\\n(that max level) and `<PerkId>HolderId` (who holds it; 0 = none). Recomputes on\\nallocate/respec (`Signals.OnPerkStateChanged`), player join, and player leave.\\nBridges Scavenger\'s Eye onto `ApplyTierMultiplier` (which `JunkService` listens for).","realm":["Server"],"source":{"line":14,"path":"src/ServerScriptService/PerkEffectsDispatcher.server.luau"}}')}}]);